const changes = $input.first().json.changes ?? [];

return changes.map(change => ({
  json: {
    file: change.new_path ?? change.old_path,
    oldFile: change.old_path ?? null,
    newFile: change.new_path ?? null,
    diff: change.diff ?? '',
    deletedFile: change.deleted_file ?? false,
    newFileAdded: change.new_file ?? false,
    renamedFile: change.renamed_file ?? false
  }
}));

const suspiciousPatterns = [
  {
    pattern: /innerHTML/i,
    reason: 'Direct assignment to innerHTML can introduce XSS.'
  },
  {
    pattern: /outerHTML/i,
    reason: 'Direct assignment to outerHTML can introduce XSS.'
  },
  {
    pattern: /document\.write\s*\(/i,
    reason: 'document.write() can inject attacker-controlled HTML.'
  },
  {
    pattern: /bypassSecurityTrustHtml\s*\(/i,
    reason: 'Bypassing Angular HTML sanitization can introduce XSS.'
  }
];

const diff = $json.diff ?? '';
const file = $json.file;

// The n8n workflow contains the detector's own security patterns.
// Do not analyze the workflow definition itself.
if (file.endsWith('n8n.json')) {
  return {
    json: {
      file,
      findings: [],
      suspicious: false
    }
  };
}

const lines = diff.split('\n');

let newLineNumber = 0;
const findings = [];

for (const line of lines) {

  // Parse diff hunk header, e.g.:
  // @@ -10,5 +20,7 @@
  const hunkMatch = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);

  if (hunkMatch) {
    newLineNumber = Number(hunkMatch[1]);
    continue;
  }

  // Skip file headers
  if (line.startsWith('+++')) {
    continue;
  }

  // Added line
  if (line.startsWith('+')) {
    const code = line.slice(1);

    for (const rule of suspiciousPatterns) {
      if (rule.pattern.test(code)) {
        findings.push({
          line: newLineNumber,
          code,
          reason: rule.reason
        });
      }
    }

    newLineNumber++;
    continue;
  }

  // Deleted line: exists only in old version
  if (line.startsWith('-')) {
    continue;
  }

  // Context line: exists in both versions
  if (line.startsWith(' ') || line === '') {
    newLineNumber++;
  }
}

return {
  json: {
    file,
    findings,
    suspicious: findings.length > 0
  }
};

const items = $input.all();

const findings = [];

for (const item of items) {
  const rawOutput = item.json.output;

  // Ignore empty agent responses
  if (!rawOutput || typeof rawOutput !== 'string') {
    continue;
  }

  let result;

  try {
    result = JSON.parse(rawOutput);
  } catch {
    // Ignore malformed agent responses for now
    continue;
  }

  // Ignore empty/malformed results
  if (!result || !result.file || !Array.isArray(result.findings)) {
    continue;
  }

  for (const finding of result.findings) {
    findings.push({
      file: result.file,
      line: finding.line ?? null,
      code: finding.code ?? null,
      reason: finding.description ?? null
    });
  }
}

return [
  {
    json: {
      suspicious: findings.length > 0,
      findings,
      findingCount: findings.length,
      affectedFiles: [...new Set(findings.map(f => f.file))]
    }
  }
];

return { 
  output:'OWASP Checker: No suspicious security patterns were detected in the changes introduced by this merge request.'
};

